refused_program.body:
git fetch {upstream_remote}
git merge --no-edit {upstream_remote}/{upstream_branch} || true
tmp=$(mktemp -d)
for f in $(git diff --name-only --diff-filter=U); do
  git show ":1:$f" > "$tmp/base"
  git show ":2:$f" > "$tmp/ours"
  git show ":3:$f" > "$tmp/theirs"
  awk -v bf="$tmp/base" -v of="$tmp/ours" -v tf="$tmp/theirs" '
  function key(s,   p) {
    p = index(s, "=")
    if (p > 0) s = substr(s, 1, p - 1)
    gsub(/^[ \t]+/, "", s)
    gsub(/[ \t]+$/, "", s)
    return s
  }
  BEGIN {
    while ((getline l < bf) > 0) b[l] = 1
    close(bf)
    while ((getline l < of) > 0) { o[++on] = l; os[l] = 1 }
    close(of)
    while ((getline l < tf) > 0) t[++tn] = l
    close(tf)
    for (i = 1; i <= tn; i++) {
      l = t[i]
      if ((l in b) && !(l in os)) continue
      r[++rn] = l
      if (!(l in rs)) { rs[l] = 1; rk[key(l)] = 1 }
    }
    last = ""
    for (i = 1; i <= on; i++) {
      l = o[i]
      if (l in rs) { last = l; continue }
      if (l in b) continue
      if (key(l) in rk) continue
      if (last == "") pre[++pn] = l
      else { na[last]++; ins[last, na[last]] = l }
    }
    for (i = 1; i <= pn; i++) print pre[i]
    for (i = 1; i <= rn; i++) {
      print r[i]
      if (r[i] in na) for (j = 1; j <= na[r[i]]; j++) print ins[r[i], j]
    }
  }
  ' > "$f"
  git add "$f"
done
if git rev-parse -q --verify MERGE_HEAD > /dev/null; then
  git commit --no-edit
fi
rm -rf "$tmp"
